import {loadMammoth,extractDocxResume,restoreOriginalLists} from './docx-text.mjs?v=159';
import {retainedResumeFile} from './resume-file-store.mjs?v=126';
import {createResumePdf} from './resume-pdf.mjs?v=159';
import {setupGeminiTailoring} from './gemini-tailoring-ui.mjs?v=164';
import {CATALOG,contains,evidenceFor} from './resume-tools.mjs?v=113';
import {formatSkillSections} from './skill-format.mjs?v=113';
import {assertResumeHeader} from './resume-header.mjs?v=113';
import {browserWordResume,downloadLocal,printableResume,printCss} from './browser-documents.mjs?v=117';
export function compareLocally(resume,description){return CATALOG.filter(skill=>contains(description,skill)).map(skill=>({skill,job:evidenceFor(description,skill)[0]||'',resume:evidenceFor(resume,skill)[0]||''}));}
let openEditor=null;
export function openJobResume(options={}){if(!openEditor)setupFreeResumeTools();openEditor(options);}
export function setupFreeResumeTools(){
 if(openEditor)return;
 const dialog=document.createElement('dialog');dialog.className='public-guide free-resume-tools';dialog.innerHTML='<button type="button" class="inbox-close" aria-label="Close resume editor">×</button><h2>Tailor your resume</h2><p>Use Gemini for a full-resume review and approve meaningful changes for this role. You can also format and download a draft without AI.</p><label>Job description (optional)<textarea data-description rows="5" maxlength="80000" placeholder="Paste the role’s requirements here"></textarea></label><details><summary>Optional keyword comparison</summary><button type="button" class="secondary" data-compare>Compare keywords</button><div data-evidence></div></details><h3>Your download draft</h3><p>Formatting keeps your facts. You can edit this draft yourself; it never replaces the original resume used for matching.</p><label>Resume draft<textarea data-draft rows="12" maxlength="150000"></textarea></label><div class="permission-actions"><button type="button" class="secondary" data-format>Format skills and spacing</button><button type="button" class="secondary" data-reset>Restore original</button></div><label>Body font size<select data-font><option>11</option><option>10.5</option><option>10</option></select> pt · Calibri in Word</label><label class="autofill-confirm"><input type="checkbox" data-reviewed> I reviewed this draft and confirm its content.</label><div class="permission-actions"><button type="button" data-word>Download Word draft</button><button type="button" class="secondary" data-print>Download one-page PDF</button><button type="button" class="secondary" data-text>Download text</button></div><p role="status" data-status></p>';
 document.body.append(dialog);const q=s=>dialog.querySelector(s),draft=q('[data-draft]'),status=q('[data-status]');let source='',activeJob={},editorGeneration=0;
 openEditor=({description='',draft:initialDraft,title='',company=''}={})=>{const generation=++editorGeneration;activeJob={title,company};source=document.getElementById('resume-text').value;status.textContent=source.trim()?'Review your resume for this role.':'Upload or paste your resume on NextRole first.';draft.value=initialDraft??source;q('[data-description]').value=description;q('[data-reviewed]').checked=false;q('[data-evidence]').replaceChildren();gemini.refresh();dialog.showModal();recoverOriginalBullets(generation,draft.value);};q('.inbox-close').onclick=()=>{editorGeneration++;gemini.stop();dialog.close();};dialog.addEventListener('cancel',()=>{editorGeneration++;gemini.stop();});
 const gemini=setupGeminiTailoring(dialog,{getSource:()=>document.getElementById('resume-text').value,getDraft:()=>draft.value,setDraft:text=>{draft.value=text;invalidate();},getDescription:()=>q('[data-description]').value,getJob:()=>activeJob});
 async function recoverOriginalBullets(generation,snapshot){
  if(/^\s*[-*•●▪◦‣–—]\s+/m.test(snapshot))return;
  try{const file=await retainedResumeFile(source);if(!file||!file.name.toLowerCase().endsWith('.docx')||generation!==editorGeneration)return;
   q('[data-review]').disabled=true;status.textContent='Checking original Word bullet formatting…';
   const formatted=await extractDocxResume(await loadMammoth(),await file.arrayBuffer()),restored=restoreOriginalLists(snapshot,formatted);
   if(generation===editorGeneration&&draft.value===snapshot&&restored!==snapshot){draft.value=restored;invalidate();status.textContent='Original bullet structure restored from your saved Word resume.';}
  }catch{if(generation===editorGeneration)status.textContent='Your current draft is ready. Re-upload the original Word resume if its bullets are missing.';}
  finally{if(generation===editorGeneration&&q('[data-cancel]').hidden)q('[data-review]').disabled=false;}
 }
 function changed(){dialog.dispatchEvent(new Event('local-draft-changed'));}
 const invalidate=()=>{changed();q('[data-reviewed]').checked=false;status.textContent='Draft changed. Review it before downloading.';};draft.oninput=invalidate;
 q('[data-reset]').onclick=()=>{draft.value=source;invalidate();};q('[data-format]').onclick=()=>{draft.value=formatSkillSections(draft.value).replace(/\t/g,'  ').split('\n').map(s=>s.trimEnd()).join('\n');invalidate();};
 q('[data-compare]').onclick=()=>{const host=q('[data-evidence]');host.replaceChildren();if(!source.trim()||q('[data-description]').value.trim().length<40){host.textContent='Upload your resume and paste the full job description first.';return;}const rows=compareLocally(source,q('[data-description]').value),note=document.createElement('p');note.textContent='Keyword evidence only—not an eligibility score. A mention may be negated or describe limited exposure. Check every qualification and do not add skills you do not possess.';host.append(note);for(const row of rows){const card=document.createElement('article');card.className='local-evidence';const h=document.createElement('strong');h.textContent=row.skill+' · '+(row.resume?'Mention found':'Not found in resume');const j=document.createElement('p');j.textContent='Job: '+row.job;const r=document.createElement('p');r.textContent='Resume: '+(row.resume||'No matching mention found.');card.append(h,j,r);host.append(card);}if(!rows.length)host.append(document.createTextNode('No recognized skills found. Compare the requirements manually.'));};
 function approved(){if(document.getElementById('resume-text').value!==source)throw Error('Your original resume changed. Reopen the resume editor from the job details.');if(!q('[data-reviewed]').checked)throw Error('Review the draft and select the confirmation first.');assertResumeHeader(draft.value);return draft.value;}
 function fits(text,size){const paper=document.createElement('div');paper.style.cssText='position:absolute;left:-10000px;width:179.52mm;font-family:Calibri,"Segoe UI",Arial,sans-serif;font-size:'+size+'pt;';paper.innerHTML='<style>'+printCss.replace(/body\{/g,'.local-paper{').replace(/p\{/g,'.local-paper p{').replace(/\.name\{/g,'.local-paper .name{').replace(/\.heading\{/g,'.local-paper .heading{')+'</style><div class="local-paper">'+printableResume(text,size)+'</div>';document.body.append(paper);const height=paper.getBoundingClientRect().height;paper.remove();return height<=1026;}
 q('[data-word]').onclick=()=>{try{const text=approved(),requested=Number(q('[data-font]').value),size=[11,10.5,10].filter(n=>n<=requested).find(n=>fits(text,n));if(!size)throw Error('This approved draft exceeds one page at 10 pt in the browser layout. Approve further wording reductions before exporting. Nothing was deleted.');q('[data-font]').value=String(size);downloadLocal(browserWordResume(text,size),'nextrole-resume.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');status.textContent='Word draft downloaded in Calibri '+size+' pt. Approved text is preserved; verify final page count in Word.';}catch(e){status.textContent=e.message;}};
 q('[data-text]').onclick=()=>{try{downloadLocal(approved(),'nextrole-resume.txt','text/plain;charset=utf-8');status.textContent='Text draft downloaded.';}catch(e){status.textContent=e.message;}};
 q('[data-print]').onclick=async()=>{const button=q('[data-print]');button.disabled=true;try{const text=approved();status.textContent='Preparing your one-page PDF…';const result=await createResumePdf(text,{requestedSize:Number(q('[data-font]').value)});if(text!==draft.value)throw Error('The draft changed during export. Review it and download again.');q('[data-font]').value=String(result.fontSize);downloadLocal(result.bytes,'nextrole-resume.pdf','application/pdf');status.textContent='PDF downloaded · 1 page · '+result.font+' '+result.fontSize+' pt. Bullets and approved content are preserved.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
}
